19	const PROCESSING_FEE = 5;
20	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
21	
22	const BASE_PREMIUMS: Record<string, number> = {
23	  sword: 100,
24	  amulet: 60,
25	  staff: 80,
26	  potion: 40,
27	  rune: 25,
28	};
29	
30	const sum = (amounts: number[]): number =>
31	  amounts.reduce((total, amount) => total + amount, 0);
32	
33	const basePremiumOf = (item: Item): number => BASE_PREMIUMS[item.type];
34	
35	const roundedInMHPCOsFavour = (premium: number): number => Math.ceil(premium);
36	
37	const quotePremium = (items: Item[]): number => {
38	  const basePremium = sum(items.map(basePremiumOf));
39	  const firstInsuranceSurcharge = basePremium * FIRST_INSURANCE_SURCHARGE_RATE;
40	
41	  return roundedInMHPCOsFavour(
42	    basePremium + firstInsuranceSurcharge + PROCESSING_FEE,
43	  );
44	};
45	
46	export const runScenario = (scenario: Scenario): ScenarioResult => ({
47	  results: scenario.steps.map((step) => ({
48	    premium: quotePremium(step.items),
49	  })),
50	});
